SELECT SUM(value) AS total_gross_mrr_ytd
FROM (
  SELECT value
  FROM "__metric__gross_mrr" -- metric materialized table
  WHERE subscription__started_date__day >= '2026-01-01' AND subscription__started_date__day <= '2026-07-12'
) t;

SELECT metric_time::date as week_start, activity__platform, SUM(value) AS weekly_active_users
FROM (
  SELECT metric_time::date, activity__platform, value
  FROM query_metric_result_active_users_last_week_placeholder
) GROUP BY 1,2;

SELECT SUM(EXTRACT(EPOCH FROM (session_end_ts - session_start_ts)))/60.0 AS total_minutes, COUNT(DISTINCT user_id) AS users
FROM fct_sessions
WHERE session_date BETWEEN '2026-07-06' AND '2026-07-12' AND is_internal = FALSE;

SELECT SUM(value) AS total_started_in_june
FROM (
  SELECT value FROM query_result_table
) t;

SELECT SUM(value) as total_mrr_from_q2_starts
FROM (
  SELECT value
  FROM metric_mrr
  WHERE subscription__started_date >= '2026-04-01' AND subscription__started_date <= '2026-06-30'
) t;

SELECT sum(value) as week_total FROM (
  SELECT value FROM query_result_r2
)

SELECT activity_date as day, SUM(duration_seconds)/60.0 AS minutes
FROM (
  SELECT date(timestamp_trunc(completed_ts, day)) as activity_date, 0 as duration_seconds FROM fct_value_moments LIMIT 0
) LIMIT 0;

