SELECT SUM(open_seconds)/60.0 AS total_minutes FROM (
  SELECT user_id, SUM(duration_seconds) AS open_seconds
  FROM (
    SELECT user_id, (EXTRACT(EPOCH FROM session_end) - EXTRACT(EPOCH FROM session_start))::bigint AS duration_seconds
    FROM fct_sessions
    WHERE session_start::date BETWEEN DATE '2026-07-06' AND DATE '2026-07-12'
  ) s
  GROUP BY user_id
) t;
